// 16 Oct 2026: ES update - 'delete account' uses eliminar, not borrar (14 keys, linguist edits allowed by user).
// Row: [pidIdx, key_id, iso, hash(current), hash(proposed), [[offset, old, new], ...]]
const PIDS = ["964775386a3ce03ecca883.03770715", "852017176a3ce11141ecd5.60405885", "2944050668d5010cbd95e8.36175908", "691331356a3b9a68428ab3.43540470", "14240418673f52ae29a007.74392007", "60625870676151e1da46d0.81913446"];
const ROWS = [[0, 885760422, "es", 3454009300, 3012951667, [[20, "borrar tu cuenta", "eliminar tu cuenta"]]], [0, 885760421, "es", 376361557, 912805285, [[0, "Borrar...", "Eliminando..."]]], [1, 917356566, "es", 212887026, 3017968629, [[10, "se ha borrado", "se ha eliminado"]]], [1, 917356567, "es", 212887026, 3017968629, [[10, "se ha borrado", "se ha eliminado"]]], [1, 917356570, "es", 2422204082, 2099226037, [[25, "se ha borrado", "se ha eliminado"]]], [1, 917356571, "es", 1546489807, 2036309608, [[25, "se ha borrado", "se ha eliminado"]]], [2, 894213034, "es", 3454009300, 3012951667, [[20, "borrar tu cuenta", "eliminar tu cuenta"]]], [3, 881149368, "es", 3454009300, 3012951667, [[20, "borrar tu cuenta", "eliminar tu cuenta"]]], [3, 905828601, "es", 1931017412, 440090883, [[0, "Cuenta borrada", "Cuenta eliminada"]]], [3, 910332808, "es", 3426109594, 3938798461, [[22, "se han borrado", "se han eliminado"]]], [4, 569687267, "es", 2818626579, 588830292, [[0, "Borrar cuenta", "Eliminar cuenta"]]], [4, 582161721, "es", 376361557, 912805285, [[0, "Borrar...", "Eliminando..."]]], [5, 756259494, "es", 2818626579, 588830292, [[0, "Borrar cuenta", "Eliminar cuenta"]]], [5, 756260583, "es", 2680107355, 2200326524, [[0, "Borrar", "Eliminar"]]]];
const by = {};
for (const [pi, key_id, iso, hc, hn, ed] of ROWS) { const pid = PIDS[pi]; (by[pid] = by[pid] || { pid, project: pid, changes: [] }).changes.push({ key_id: String(key_id), iso, hc, hn, ed, allow_ling: true }); }
return Object.values(by).map(p => ({ json: Object.assign(p, { ids: [...new Set(p.changes.map(c => c.key_id))].join(','), n_keys: p.changes.length, skipped_excluded: 0 }) }));

// Live text must hash to 'current'; edits applied from the end; result must hash to 'proposed'. Linguist editors skipped unless the row has allow_ling. Markup/char-limit guards.
const LING = new Set(["47natcha@gmail.com", "arandatrad@gmail.com", "austra.muizniece@gmail.com", "boh.vozniuk@gmail.com", "bruno@bsttranslations.com", "daniel@dgmultilingualservices.com", "dmluciahorea@gmail.com", "ellen.de.venter@outlook.com", "farahputri@gmail.com", "harald.roald@gmail.com", "ilaria.roncaglia@gmail.com", "ivanaturcin@ymail.com", "jaromirvicari@me.com", "julius.valkiunas@gmail.com", "karahansisman@gmail.com", "katri.varvikko@gmail.com", "kenneth@phraseit.dk", "marit.teichmann@gmail.com", "michal.tosza@translators.org.pl", "mjlocalize@gmail.com", "mteixeira@sacradomus.com", "mteres@terestraducciones.com", "nerissaneptuno@gmail.com", "qrcodelocalization@gmail.com", "quentinnguyen.localize@gmail.com", "root-translations@outlook.com", "roxanamoldovan25@gmail.com", "ruckova.lucia@gmail.com", "sabrathan@gmail.com", "sara.guinot.trad@gmail.com", "silis.martins@gmail.com", "silke.luehrmann@gmx.de", "straus.translations@gmail.com", "therese.svardsten@gmail.com", "translation@cornell.hu", "vidiasc@gmail.com"]);
function h(s){let x=5381;for(let i=0;i<s.length;i++){x=(Math.imul(x,33)^s.charCodeAt(i))>>>0;}return x;}
const tags = s => (String(s).match(/<\/?[a-zA-Z][a-zA-Z0-9]*\b[^>]*>/g) || []).map(t => t.replace(/\s+/g, ' ').toLowerCase()).join('|');
const phs = s => (String(s).match(/\{\{[^}]*\}\}|\{[^{}]*\}|\[%[^\]]*\]|%\d*\$?[sd]/g) || []).sort().join('|');
const plans = $('Plan').all().map(i => i.json); const res = $input.all().map(i => i.json || {});
const KEYS = {};
res.forEach((r, i) => { const pid = r.project_id || (plans[i] || {}).pid; if (Array.isArray(r.keys)) for (const k of r.keys) KEYS[pid + '|' + k.key_id] = k; });
return plans.map((p, i) => {
  const ok = Array.isArray((res[i] || {}).keys); const results = []; const writes = {};
  for (const c of p.changes) {
    const k = KEYS[p.pid + '|' + c.key_id]; const kname = k && k.key_name ? (k.key_name.web || k.key_name.other) : c.key_id;
    const base = { project: p.project, key: kname, lang: c.iso, iso: c.iso };
    if (!ok) { results.push(Object.assign({}, base, { status: 'fetch_failed' })); continue; }
    if (!k) { results.push(Object.assign({}, base, { status: 'key_not_found' })); continue; }
    if (k.is_archived) { results.push(Object.assign({}, base, { status: 'key_archived' })); continue; }
    const t = (k.translations || []).find(x => x.language_iso === c.iso);
    if (!t) { results.push(Object.assign({}, base, { status: 'language_not_found' })); continue; }
    const live = String(t.translation || '');
    if (h(live) === c.hn) { results.push(Object.assign({}, base, { status: 'already_consistent' })); continue; }
    if (h(live) !== c.hc) { results.push(Object.assign({}, base, { status: 'skipped_changed' })); continue; }
    if (!c.allow_ling && LING.has(String(t.modified_by_email || ''))) { results.push(Object.assign({}, base, { status: 'skipped_linguist' })); continue; }
    let s = live; let bad = false;
    for (const [off, a, b] of c.ed.slice().reverse()) { if (s.substr(off, a.length) !== a) { bad = true; break; } s = s.slice(0, off) + b + s.slice(off + a.length); }
    if (bad || h(s) !== c.hn) { results.push(Object.assign({}, base, { status: 'skipped_patch_mismatch' })); continue; }
    if (tags(s) !== tags(live) || phs(s) !== phs(live)) { results.push(Object.assign({}, base, { status: 'skipped_markup' })); continue; }
    if ((k.char_limit || 0) > 0 && s.length > k.char_limit) { results.push(Object.assign({}, base, { status: 'skipped_limit' })); continue; }
    (writes[c.key_id] = writes[c.key_id] || []).push({ language_iso: t.language_iso, translation: s });
    results.push(Object.assign({}, base, { status: 'to_apply', key_id: c.key_id, language_iso: t.language_iso, proposed: s, prev_editor: String(t.modified_by_email || '') }));
  }
  const keys = Object.keys(writes).map(id => ({ key_id: Number(id), translations: writes[id] }));
  return { json: { pid: p.pid, project: p.project, n_write: keys.length, n_tr: results.filter(x => x.status === 'to_apply').length, body: JSON.stringify({ keys }), results } };
});

const D = $('Decide').all().map(i => i.json);
const resp = {}; for (const it of $input.all()) { const j = it.json || {}; if (j.project_id) resp[j.project_id] = j; }
const counts = {}; const issues = []; const perProject = [];
for (const d of D) {
  const r = resp[d.pid];
  const live = {}; if (r && Array.isArray(r.keys)) for (const k of r.keys) for (const t of (k.translations || [])) live[k.key_id + '|' + t.language_iso] = t.translation;
  const errIds = new Set(((r && r.errors) || []).map(e => String(e.key_id || (e.key || {}).key_id || '')));
  let applied = 0;
  for (const x of d.results) {
    let st = x.status;
    if (st === 'to_apply') {
      const v = live[x.key_id + '|' + x.language_iso];
      if (v === x.proposed && !errIds.has(String(x.key_id))) { st = 'applied'; applied++; }
      else { st = 'write_unconfirmed'; issues.push({ project: x.project, lang: x.lang, key: x.key, status: st, note: r ? JSON.stringify(r.error || '').slice(0, 120) : 'no response' }); }
    } else if (st !== 'already_consistent') { issues.push({ project: x.project, lang: x.lang, key: x.key, status: st, note: x.note || '' }); }
    counts[st] = (counts[st] || 0) + 1;
  }
  perProject.push({ project: d.project, applied, total: d.results.length });
}
return [{ json: { counts, perProject, issues, skipped_excluded: $('Plan').first().json.skipped_excluded } }];
